"""Write RR search log, sources inventory, existing datasets CSVs (Phase 0)."""
import csv

P = "01_discovery/_parts/"
LOG = str(__import__("pathlib").Path(__file__).resolve().parents[1] / "logs" / "phase0_RR_log.tsv")

rows = []
for line in open(LOG, encoding="utf-8"):
    line = line.rstrip("\n")
    if not line.strip():
        continue
    p = line.split("\t")
    p += [""] * (6 - len(p))
    rows.append(dict(date="2026-10-06", agent="RR", engine_site=p[0], query=p[1], language=p[2],
                     n_results=p[3], useful_hits=p[4], notes=p[5]))
with open(P + "RR_search_log.csv", "w", newline="", encoding="utf-8") as fh:
    w = csv.DictWriter(fh, fieldnames=["date", "agent", "engine_site", "query", "language", "n_results", "useful_hits", "notes"])
    w.writeheader()
    w.writerows(rows)
print("log rows", len(rows))

